changeSet.sql:
INSERT INTO plugins ( identifier, name, description, javascriptModuleFile, functionsViewTemplate, settingsViewTemplate, namelocalizationkey, settingsPermission, functionsPermission, deviceFunctionsPermission, enabledForDevice ) VALUES ( 'rustdesk', 'RustDesk', 'RustDesk remote desktop provisioning, permission management, and self-hosted server integration', 'app/components/plugins/rustdesk/rustdesk.module.js', 'app/components/plugins/rustdesk/views/rustdesk.html', 'app/components/plugins/rustdesk/views/settings.html', 'plugin.rustdesk.localization.key.name', 'plugin_rustdesk_settings', 'plugin_rustdesk_access', 'plugin_rustdesk_access', TRUE );
INSERT INTO permissions (name, description) VALUES ('plugin_rustdesk_access', 'Can view RustDesk status and trigger device actions'); INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq')); INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));
INSERT INTO permissions (name, description) VALUES ('plugin_rustdesk_settings', 'Can configure RustDesk server settings and APK provisioning'); INSERT INTO userRolePermissions (roleId, permissionId) VALUES (1, currval('permissions_id_seq')); INSERT INTO userRolePermissions (roleId, permissionId) VALUES (2, currval('permissions_id_seq'));
CREATE TABLE plugin_rustdesk_settings ( id SERIAL PRIMARY KEY, customerId INT NOT NULL UNIQUE REFERENCES customers (id) ON DELETE CASCADE, enabled BOOLEAN NOT NULL DEFAULT TRUE, idServer VARCHAR(255) NOT NULL DEFAULT '', relayServer VARCHAR(255) NOT NULL DEFAULT '', apiServer VARCHAR(255) NOT NULL DEFAULT '', publicKey VARCHAR(255) NOT NULL DEFAULT '', hbbsDbPath VARCHAR(512) NOT NULL DEFAULT '/opt/rustdesk/db_v2.sqlite3', hbbsKeyPath VARCHAR(512) NOT NULL DEFAULT '/opt/rustdesk/id_ed25519.pub', apkUrl VARCHAR(1024) NOT NULL DEFAULT '', apkVersion VARCHAR(64) NOT NULL DEFAULT '', autoProvision BOOLEAN NOT NULL DEFAULT TRUE, autoGrantPermissions BOOLEAN NOT NULL DEFAULT TRUE, enableInputService BOOLEAN NOT NULL DEFAULT TRUE, allowInKiosk BOOLEAN NOT NULL DEFAULT TRUE, autoStart BOOLEAN NOT NULL DEFAULT FALSE, permanentPassword VARCHAR(255) NOT NULL DEFAULT '' );
CREATE TABLE plugin_rustdesk_devices ( id SERIAL PRIMARY KEY, deviceId INT NOT NULL UNIQUE REFERENCES devices (id) ON DELETE CASCADE, customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE, installed BOOLEAN NOT NULL DEFAULT FALSE, versionName VARCHAR(64), versionCode INT, rustdeskId VARCHAR(64), peerUuid VARCHAR(128), inputServiceEnabled BOOLEAN NOT NULL DEFAULT FALSE, overlayGranted BOOLEAN NOT NULL DEFAULT FALSE, storageGranted BOOLEAN NOT NULL DEFAULT FALSE, notificationsGranted BOOLEAN NOT NULL DEFAULT FALSE, mediaProjectionGranted BOOLEAN NOT NULL DEFAULT FALSE, batteryOptimizationIgnored BOOLEAN NOT NULL DEFAULT FALSE, serverConfigured BOOLEAN NOT NULL DEFAULT FALSE, hbbsRegistered BOOLEAN NOT NULL DEFAULT FALSE, lastReportedAt BIGINT );
CREATE INDEX plugin_rustdesk_devices_customer_idx ON plugin_rustdesk_devices (customerId); CREATE INDEX plugin_rustdesk_devices_rdid_idx ON plugin_rustdesk_devices (rustdeskId);

changeSet.rollback:
DROP TABLE IF EXISTS plugin_rustdesk_devices;
DROP TABLE IF EXISTS plugin_rustdesk_settings;
DELETE FROM permissions WHERE name IN ('plugin_rustdesk_access', 'plugin_rustdesk_settings');
DELETE FROM plugins WHERE identifier = 'rustdesk';
